    "miner_3_20260730_shock_exhaustion_range_weighted_reversal_1d",
    "miner_3_20260730_vix_conditioned_clv_1d",
]
FACTOR_W = np.array([.22, .18, .10, .12, .10, .12, .08, .08])
_gate = 0


def _rank(values, symbols):
    good = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in symbols}
    if not good:
        return out
    for i, (_, s) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def _weights(score, vol, defensive):
    # In a bear regime, express risk aversion through tradable defensive assets,
    # while retaining a complete, cash-free 15-asset target.
    raw = {}
    for s in UNIVERSE:
        tilt = 1.0
        if defensive and s in ("XAU", "US10Y", "CN10Y"):
            tilt = 1.55
        if defensive and s in ("BTC", "ETH", "WTI"):
            tilt = .48
        raw[s] = max(.0005, (.45 + score.get(s, .5)) * tilt / max(vol.get(s, .02), .009))
    w = {s: raw[s] / sum(raw.values()) for s in UNIVERSE}
    # Lower concentration in the high-dispersion regime; redistribute caps.
    cap = .12 if defensive else .14
    for _ in range(20):
        excess = sum(max(0., x - cap) for x in w.values())
        if excess < 1e-10:
            break
        w = {s: min(x, cap) for s, x in w.items()}
        free = [s for s in UNIVERSE if w[s] < cap - 1e-12]
        base = sum(w[s] for s in free)
        for s in free:
            w[s] += excess * w[s] / max(base, 1e-12)
