            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        if len(c) >= 80 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[s], frames[s] = c, df
    syms = [s for s in UNIVERSE if s in px]
    if len(syms) < 12:
        return
    daily = {s: px[s][1:] / px[s][:-1] - 1.0 for s in syms}
    ret = lambda s, n: px[s][-1] / px[s][-n-1] - 1.0
    r10 = {s: ret(s, 10) for s in syms}
    r20 = {s: ret(s, 20) for s in syms}
    r60 = {s: ret(s, 60) for s in syms}
    vol = {s: max(float(np.std(daily[s][-30:])), .008) for s in syms}
    breadth = float(np.mean([r20[s] > 0 for s in syms]))
    dispersion = float(np.std(list(r20.values())))
    defensive = (("SPX" in px and r10["SPX"] < 0 and r20["SPX"] < 0)
                 or breadth < .45 or float(np.mean(list(vol.values()))) > .022)
    factors = [{} for _ in FACTOR_W]
    peer20 = {s: float(np.median([r20[x] for x in syms if x != s])) for s in syms}
    stress = min(2.0, max(.5, dispersion / .025))
    for s in syms:
        d, v = daily[s], vol[s]
        downside = max(float(np.std(np.minimum(d[-40:], 0))), .006)
        path = max(float(np.sum(np.abs(d[-20:]))), .03)
        hi = float(frames[s]["high"].iloc[-1]) if "high" in frames[s] else px[s][-1]
        lo = float(frames[s]["low"].iloc[-1]) if "low" in frames[s] else px[s][-1]
        clv = (px[s][-1] - lo) / max(hi - lo, 1e-9) - .5
        shock = float(np.min(d[-6:-1]))
        factors[0][s] = r20[s] / downside
        factors[1][s] = -float(np.mean(d[-5:])) / v
        # Stress-conditioned residual continuation, using only peer returns.
        factors[2][s] = stress * (r20[s] - peer20[s]) / v
        factors[3][s] = (.65 * r20[s] + .35 * r60[s]) / v
        factors[4][s] = r20[s] / path
        factors[5][s] = -float(np.mean(d[-2:])) / v
        factors[6][s] = (-shock if shock < 0 else -abs(d[-1])) / v
        factors[7][s] = clv / v
    score = {s: sum(w * _rank(f, syms)[s] for w, f in zip(FACTOR_W, factors)) for s in syms}
    targets = _weights(score, vol, defensive)
    forecasts = {s: max(0.0001, .04 * (score.get(s, .5) - .5)) for s in UNIVERSE}
    rebalance_to_weights(targets, forecast_returns=forecasts, factor_ids=FACTOR_IDS, horizon_days=10)
    _gate = 9

