    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = [
    "000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
    "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"
]
# Current Screener ensemble; seven active factors (well below the ten-factor cap).
FACTOR_IDS = [
    "miner_3_20261119_stress_conditioned_residual_20d",
    "miner_2_20261217_residual_beta_volscaled_20d",
    "miner_1_20260730_vix_state_reversal_5d",
    "miner_3_20261105_downside_risk_adjusted_momentum",
    "miner_1_20270325_vix_beta_penalized_momentum_20d",
    "miner_1_20270408_breadth_confirmed_momentum_20d",
    "miner_2_20261231_corr_adjusted_trend_20d",
]
FACTOR_WEIGHTS = np.array([.17, .17, .16, .15, .15, .10, .10])
_gate = 0


def _rank(values, symbols):
    good = sorted((float(values[s]), s) for s in symbols
                  if np.isfinite(values.get(s, np.nan)))
    out = {s: .5 for s in symbols}
    if good:
        n = len(good)
        for i, (_, s) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def _weights(score, vol, defensive):
    # Inverse volatility, score tilt, and explicit defensive substitution in bear regimes.
    raw = {}
    for s in UNIVERSE:
        tilt = 1.0
        if defensive and s in ("XAU", "US10Y", "CN10Y"):
            tilt = 2.15
        elif defensive and s in ("BTC", "ETH", "WTI"):
            tilt = .25
        raw[s] = max(.002, (.35 + score.get(s, .5)) * tilt /
                     max(vol.get(s, .02), .012))
    w = {s: raw[s] / sum(raw.values()) for s in UNIVERSE}
    cap = .12 if defensive else .14
    # Redistribute cap excess only to uncapped assets, retaining full investment.
    for _ in range(30):
        over = [s for s in UNIVERSE if w[s] > cap + 1e-12]
        if not over:
            break
        excess = sum(w[s] - cap for s in over)
        for s in over:
            w[s] = cap
        free = [s for s in UNIVERSE if s not in over]
        denom = sum(w[s] for s in free)
        for s in free:
            w[s] += excess * w[s] / max(denom, 1e-12)
    total = sum(w.values())
    return {s: max(0.0, w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _gate
    if _gate:
        _gate -= 1
        return

    prices, returns, vols = {}, {}, {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=230)
        if df is None or len(df) < 80:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) >= 80 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[s] = c
            returns[s] = c[1:] / c[:-1] - 1.0
            vols[s] = max(float(np.std(returns[s][-30:])), .008)
    symbols = [s for s in UNIVERSE if s in prices]
    if len(symbols) < 12:
        return

    r5 = {s: prices[s][-1] / prices[s][-6] - 1.0 for s in symbols}
    r20 = {s: prices[s][-1] / prices[s][-21] - 1.0 for s in symbols}
    r60 = {s: prices[s][-1] / prices[s][-61] - 1.0 for s in symbols}
    peer = np.mean([returns[s][-20:] for s in symbols], axis=0)

    vix_level = 0.0
    vd = get_index_daily_data(symbol="VIX", days=35)
    if vd is not None and len(vd) >= 22:
        v = np.asarray(vd.sort_values("date")["close"], dtype=float)
        vix_level = max(0.0, v[-1] / max(np.median(v[-21:]), 1e-9) - 1.0)
    breadth = np.mean([r20[s] > 0 for s in symbols])
    spx_bear = r20.get("SPX", 0.0) < 0 and r5.get("SPX", 0.0) < 0
    defensive = spx_bear or breadth < .45 or np.mean(list(vols.values())) > .022 or vix_level > .15

    factors = [dict() for _ in FACTOR_WEIGHTS]
    for s in symbols:
        d = returns[s]
        downside = max(float(np.std(np.minimum(d[-40:], 0.0))), .006)
