    forecast = {s: max(.0001, .025 * (score.get(s, .5) - .5)) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=FACTOR_IDS, horizon_days=10)
    _gate = 9

