        factors[s] = [
            (r20[s] + .5*r40[s]) / vol[s] - .5*dn/vol[s], # stress resilience
            (r20[s] - r60[s]/3) / dn,                    # recovery/downside trend
            (r10[s] - r20[s]/2) / vol[s],                # acceleration
