            r40[s]/vol[s] + .25*(np.mean(x > 0)-.5),    # breadth/quality
            (.55*r20[s] + .45*r40[s]) / dn,              # downside trend
            (r20[s]/vol[s]) * (1-min(vol[s]/.04, .75)), # volatility-conditioned efficiency
            (r20[s] - .7*med20) / vol[s]                 # defensive relative lead
        ]
    ranks = [rank({s: factors[s][j] for s in names}) for j in range(8)]
    score = {s: (sum(W[j]*(ranks[j][s]-.5) for j in range(8)) if s in names else 0.0) for s in U}
    breadth = np.mean([r20[s] > 0 for s in names])
    vix = 0.0
    vd = get_index_daily_data(symbol="VIX", days=55)
    if vd is not None and len(vd) > 22:
        vc = np.asarray(vd.sort_values("date")["close"], float)[:-1]
        if len(vc) >= 22 and np.all(np.isfinite(vc)): vix = float(vc[-1])
