import numpy as np
from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
    get_index_daily_data, get_account_dict, rebalance_to_weights)

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
F = [
    "miner_3_20280727_multihorizon_consistency_20d",
    "miner_3_20290628_residual_momentum_volscaled_20",
    "macro_stress_resilience_20d", "stable_asymmetry_40_60",
    "miner_1_20281116_defensive_relative_lead_20d",
    "breadth_vol_quality_40d", "miner_1_20291227_short_reversal_volscaled_20d",
    "drift_vol_compression_20_60_reval"
]
W = [0.22, 0.16, 0.14, 0.13, 0.11, 0.10, 0.09, 0.05]
_days_to_decision = 0

def rank(v):
    a = sorted(v, key=lambda s: (v[s], s))
    return {s: (i + 1.0) / max(len(a), 1) for i, s in enumerate(a)}

def capped(raw, cap=0.15):
    # Iterative cap, then exact normalization across all 15 tradable assets.
    out = {}; active = set(U); left = 1.0
    while active:
        z = sum(max(raw[s], .001) for s in active)
        hit = [s for s in active if left * max(raw[s], .001) / z > cap]
        if not hit:
            for s in active: out[s] = left * max(raw[s], .001) / z
            break
        for s in hit:
            out[s] = cap; left -= cap; active.remove(s)
    z = sum(out.values())
    return {s: out[s] / z for s in U}

@register_hook
def cross_asset_strategy():
    global _days_to_decision
    if _days_to_decision:
        _days_to_decision -= 1
        return
    px = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=280)
        if d is None or len(d) < 125: continue
        c = np.asarray(d.sort_values("date")["close"], float)[:-1]
        if len(c) >= 120 and np.all(np.isfinite(c)) and np.all(c > 0): px[s] = c
    names = [s for s in U if s in px]
    if len(names) < 12: return
    ret = {s: px[s][1:] / px[s][:-1] - 1.0 for s in names}
    vol = {s: max(float(np.std(ret[s][-40:])), .008) for s in names}
    r10 = {s: px[s][-1] / px[s][-11] - 1 for s in names}
    r20 = {s: px[s][-1] / px[s][-21] - 1 for s in names}
    r40 = {s: px[s][-1] / px[s][-41] - 1 for s in names}
    r60 = {s: px[s][-1] / px[s][-61] - 1 for s in names}
    med20 = float(np.median(list(r20.values())))
    # Practical proxies preserve ensemble intent: persistence, residual trend,
    # stress resilience, asymmetry, defensive relative leadership, breadth quality,
    # bounded reversal, and compression/revaluation.
    f = {s: [] for s in names}
    for s in names:
        x = ret[s][-60:]; dn = max(float(np.std(x[x < 0])) if np.any(x < 0) else .01, .01)
        up = max(float(np.std(x[x > 0])) if np.any(x > 0) else .01, .005)
        breadth = float(np.mean(x > 0))
        persistence = .45*r20[s] + .35*r40[s] + .20*r60[s]
        residual = (r20[s] - med20) / vol[s]
        stress = (.55*r20[s] + .45*r40[s]) / vol[s] + .35*breadth
        asym = persistence / dn + .12*up / dn
        defensive = r40[s]/vol[s] + .20*breadth
        quality = persistence/dn + .25*breadth - .20*vol[s]/.02
        reversal = -(r10[s] - .5*r20[s]) / vol[s]
        compression = -(vol[s] / max(float(np.std(ret[s][-120:])), .008)) + .25*r60[s]/vol[s]
        f[s] = [persistence, residual, stress, asym, defensive, quality, reversal, compression]
    rr = [rank({s: f[s][j] for s in names}) for j in range(8)]
    score = {s: (sum(W[j] * (rr[j][s] - .5) for j in range(8)) if s in names else 0.0) for s in U}
    breadth = float(np.mean([r20[s] > 0 for s in names]))
    vix = 0.0; vd = get_index_daily_data(symbol="VIX", days=55)
    if vd is not None and len(vd) > 22:
        vc = np.asarray(vd.sort_values("date")["close"], float)[:-1]
        if len(vc) >= 22 and np.all(np.isfinite(vc)): vix = float(vc[-1])
    high_risk = breadth < .40 or r20.get("SPX", med20) < -.05 or np.mean(list(vol.values())) > .022 or vix >= 20
    tilt = {s: 1.0 for s in U}
    if high_risk:
        tilt.update({"XAU":1.30, "US10Y":1.22, "CN10Y":1.15, "BTC":.82, "ETH":.80, "WTI":.90, "COPPER":.92})
    raw = {s: tilt[s] * (.51 + score[s]) / max(vol.get(s, .02), .008)**.20 for s in U}
    target = capped(raw)
    account = get_account_dict(); assets = max(float(account.get("total_assets", 0)), 1.0)
    old = {s: 0.0 for s in U}
    for p in account.get("positions", []):
        s = p.get("symbol")
        if s in old and float(p.get("quantity", 0)) > 0: old[s] = max(float(p.get("market_value", 0)), 0) / assets
    if sum(old.values()) > .001:
        target = {s: (.35*target[s] + .65*old[s]) for s in U}
        z = sum(target.values()); target = {s: target[s]/z for s in U}
    forecast = {s: float(.012 * score[s] * (.8 if high_risk else 1.0)) for s in U}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=F, horizon_days=10)
    _days_to_decision = 9

