W = [0.22, 0.14, 0.14, 0.11, 0.09, 0.08, 0.07, 0.06, 0.05, 0.04]
DAYS = 0

def ranks(x):
    a = sorted(x, key=lambda s: (x[s], s))
    return {s:(i+1.0)/len(a) for i,s in enumerate(a)}

def cap_weights(raw, cap=.15):
    # Iterative cap, retaining a complete 15-asset vector.
    out={}; active=set(U); left=1.0
    while active:
        z=sum(max(raw[s],1e-6) for s in active)
        hit=[s for s in active if left*max(raw[s],1e-6)/z>cap]
