import numpy as np
from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
    get_index_daily_data, get_account_dict, rebalance_to_weights)

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
     "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
F = [
    "miner_3_20310904_recovery_pullback_20d",
    "miner_1_20280323_vix_conditioned_efficiency_trend",
    "miner_3_20290628_residual_momentum_volscaled_20",
    "miner_1_20281116_defensive_relative_lead_20d",
    "breadth_vol_quality_40d",
    "drift_vol_compression_20_10_40",
    "miner_3_20280907_downside_asymmetry_quality_30d",
]
W = [0.22, 0.18, 0.14, 0.13, 0.12, 0.11, 0.10]
WAIT = 0


def cs_rank(values):
    ordered = sorted(values, key=lambda x: (values[x], x))
    n = float(len(ordered))
    return {s: (i + 1.0) / n for i, s in enumerate(ordered)}


def cap_weights(raw, cap=0.15):
    # Iterative cap-and-renormalize; always returns every tradable asset.
    out, free, left = {}, set(U), 1.0
    while free:
        z = sum(max(raw[s], 1e-8) for s in free)
        hit = [s for s in free if left * max(raw[s], 1e-8) / z > cap]
        if not hit:
            for s in free:
                out[s] = left * max(raw[s], 1e-8) / z
            break
        for s in hit:
            out[s] = cap
            left -= cap
            free.remove(s)
    z = sum(out.values())
    return {s: out.get(s, 0.0) / z for s in U}


@register_hook
def cross_asset_strategy():
    global WAIT
    if WAIT:
        WAIT -= 1
        return

    prices = {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=280)
        if d is None:
            continue
        c = np.asarray(d.sort_values('date')['close'], dtype=float)[:-1]
        if len(c) >= 125 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[s] = c
    names = [s for s in U if s in prices]
    if len(names) < 12:
        WAIT = 9
        return

    rets = {s: prices[s][1:] / prices[s][:-1] - 1.0 for s in names}
    r10 = {s: prices[s][-1] / prices[s][-11] - 1.0 for s in names}
    r20 = {s: prices[s][-1] / prices[s][-21] - 1.0 for s in names}
    r60 = {s: prices[s][-1] / prices[s][-61] - 1.0 for s in names}
    vol20 = {s: max(float(np.std(rets[s][-20:])), .008) for s in names}
    vol40 = {s: max(float(np.std(rets[s][-40:])), .008) for s in names}
    med20 = float(np.median(list(r20.values())))

    # Observation-only VIX is used solely as a regime conditioning input.
    vix = 20.0
    vd = get_index_daily_data(symbol='VIX', days=65)
    if vd is not None:
        vc = np.asarray(vd.sort_values('date')['close'], dtype=float)[:-1]
        if len(vc) >= 22 and np.all(np.isfinite(vc)):
            vix = float(vc[-1])
            vix_median = float(np.median(vc[-60:]))
        else:
            vix_median = 20.0
    else:
        vix_median = 20.0

    vals = {s: [0.0] * len(F) for s in names}
    defensive = {'XAU', 'US10Y', 'CN10Y'}
    basket = np.mean([r20[s] for s in defensive if s in r20])
    for s in names:
        x20, x40 = rets[s][-20:], rets[s][-40:]
        downside = max(float(np.mean(np.maximum(-x40, 0))), .002)
        pos = np.maximum(x40, 0)
        breadth40 = float(np.mean(x40 > 0))
        path_eff = abs(r20[s]) / max(float(np.sum(np.abs(x20))), .02)
        # Exact ensemble intent, with lagged prices and robust neutral fallbacks.
        vals[s][0] = -(r60[s] - .70 * r10[s]) / (2.0 * downside + vol20[s])
        trend_sign = 1.0 if vix <= vix_median else -1.0
        vals[s][1] = trend_sign * (r20[s] / vol20[s]) * path_eff
        vals[s][2] = (r20[s] - med20) / vol20[s]
        vals[s][3] = (r20[s] - basket) * (.25 + .75 * (1.0 if np.mean([r20[a] > 0 for a in names]) < .40 else 0.0))
        vals[s][4] = ((breadth40 - .5) * 2.0) / max(vol40[s] * np.sqrt(252), .01)
        vals[s][5] = (r20[s] / (vol40[s] + .01)) * (1.0 - vol20[s] / (vol40[s] + .01))
        vals[s][6] = (float(np.mean(pos)) / downside) * breadth40

    ranks = [cs_rank({s: vals[s][j] for s in names}) for j in range(len(F))]
    score = {s: sum(W[j] * (ranks[j][s] - .5) for j in range(len(F))) for s in names}
    for s in U:
        score.setdefault(s, 0.0)

    breadth = float(np.mean([r20[s] > 0 for s in names]))
    stressed = breadth < .40 or vix > max(22.0, vix_median * 1.25)
    tilt = {s: 1.0 for s in U}
    if stressed:
        tilt.update({'XAU': 1.30, 'US10Y': 1.22, 'CN10Y': 1.15,
                     'BTC': .82, 'ETH': .80, 'WTI': .90, 'COPPER': .92})
    raw = {s: tilt[s] * max(.51 + score[s], .03) / max(vol20.get(s, .02), .008) ** .20 for s in U}
    target = cap_weights(raw)

    account = get_account_dict()
    assets = max(float(account.get('total_assets', 0.0)), 1.0)
    old = {s: 0.0 for s in U}
    for p in account.get('positions', []):
        s = p.get('symbol')
        if s in old and float(p.get('quantity', 0.0)) > 0:
            old[s] = max(float(p.get('market_value', 0.0)), 0.0) / assets
    if sum(old.values()) > .001:
        target = {s: .35 * target[s] + .65 * old[s] for s in U}
        z = sum(target.values())
        target = {s: target[s] / z for s in U}

    forecast = {s: float(.012 * score[s] * (.80 if stressed else 1.0)) for s in U}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=F, horizon_days=10)
    WAIT = 9

