import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    get_account_dict, rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_IDS = [
    "miner_3_20310904_recovery_pullback_20d",
    "miner_1_20311211_exhaustion_contrarian_20d",
    "miner_2_20310626_trend_acceleration_quality",
    "miner_1_20281116_defensive_relative_lead_20d",
    "miner_1_20320624_path_stability_lead_10d",
    "breadth_vol_quality_40d",
    "miner_3_20280907_downside_asymmetry_quality_30d",
    "miner_2_20320527_smooth_dispersion_pullback_10d",
    "miner_2_20311127_contrarian_residual_strength_40d",
    "miner_2_20320708_short_dispersion_pullback_5d_10d",
]
WEIGHTS = np.array([.18, .16, .14, .13, .12, .11, .06, .04, .03, .03])
WAIT = 0


def cs_rank(values):
    ordered = sorted(values, key=lambda s: (values[s], s))
    n = float(len(ordered))
    return {s: (i + 1.0) / n for i, s in enumerate(ordered)}


def cap_weights(raw, cap=.15):
    result = {s: 0.0 for s in UNIVERSE}
    active = set(UNIVERSE)
    remaining = 1.0
    while active:
        denom = sum(max(raw[s], 1e-8) for s in active)
        clipped = [s for s in active if remaining * max(raw[s], 1e-8) / denom > cap]
        if not clipped:
            for s in active:
                result[s] = remaining * max(raw[s], 1e-8) / denom
            break
        for s in clipped:
            result[s] = cap
            remaining -= cap
            active.remove(s)
    total = sum(result.values())
    return {s: result[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global WAIT
    if WAIT:
        WAIT -= 1
        return

    prices = {}
    for symbol in UNIVERSE:
        data = get_stock_daily_data(symbol=symbol, days=280)
        if data is None:
            continue
        close = np.asarray(data.sort_values("date")["close"], dtype=float)[:-1]
        if len(close) >= 125 and np.all(np.isfinite(close)) and np.all(close > 0):
            prices[symbol] = close
    if len(prices) < 12:
        WAIT = 9
        return

    names = list(prices)
    returns = {s: prices[s][1:] / prices[s][:-1] - 1.0 for s in names}
    r5 = {s: prices[s][-1] / prices[s][-6] - 1.0 for s in names}
    r10 = {s: prices[s][-1] / prices[s][-11] - 1.0 for s in names}
    r20 = {s: prices[s][-1] / prices[s][-21] - 1.0 for s in names}
    r40 = {s: prices[s][-1] / prices[s][-41] - 1.0 for s in names}
    r60 = {s: prices[s][-1] / prices[s][-61] - 1.0 for s in names}
    vol10 = {s: max(float(np.std(returns[s][-10:])), .008) for s in names}
    vol20 = {s: max(float(np.std(returns[s][-20:])), .008) for s in names}
    vol40 = {s: max(float(np.std(returns[s][-40:])), .008) for s in names}
    downside = {s: max(float(np.std(np.minimum(returns[s][-40:], 0.0))), .003) for s in names}
    breadth = {s: float(np.mean(returns[s][-40:] > 0)) for s in names}
    defensive = [s for s in ("XAU", "US10Y", "CN10Y") if s in names]
    defensive_lead = float(np.mean([r20[s] for s in defensive])) if defensive else 0.0

    signals = {}
    for s in names:
        # These are lagged, rank-based implementations of the persisted factors.
        signals[s] = [
            (-r10[s] - .30 * r20[s]) / vol20[s],
            (-r10[s] + .20 * r40[s] - .20 * r60[s]) / vol20[s],
            (r10[s] + .50 * r20[s] - .25 * r60[s]) / vol20[s],
            (r20[s] - defensive_lead) / vol40[s],
            (-vol10[s] + breadth[s]) / vol20[s],
            (breadth[s] - .50) / vol40[s] - .25 * vol40[s],
            (r20[s] - .50 * max(-r40[s], 0.0)) / downside[s],
            (-r5[s] + .25 * r10[s]) / vol10[s],
            (r40[s] - .50 * r20[s]) / vol40[s],
            (-r5[s] + .10 * r20[s]) / vol10[s],
        ]
    ranks = [cs_rank({s: signals[s][j] for s in names}) for j in range(10)]
    score = {s: sum(WEIGHTS[j] * (ranks[j][s] - .5) for j in range(10)) for s in names}
    score.update({s: 0.0 for s in UNIVERSE if s not in score})

    stress = sum(r20[s] > 0 for s in names) / len(names) < .40
    vix = get_index_daily_data(symbol="VIX", days=65)
    if vix is not None:
        vc = np.asarray(vix.sort_values("date")["close"], dtype=float)[:-1]
        if len(vc) >= 22 and np.all(np.isfinite(vc)):
            stress = stress or vc[-1] > max(22.0, 1.25 * float(np.median(vc[-60:])))
    tilt = {s: 1.0 for s in UNIVERSE}
    if stress:
        tilt.update({"XAU": 1.35, "US10Y": 1.25, "CN10Y": 1.18,
                     "BTC": .72, "ETH": .70, "WTI": .84, "COPPER": .88})
    raw = {s: tilt[s] * max(.51 + score[s], .03) / max(vol20.get(s, .02), .008) ** .20 for s in UNIVERSE}
    target = cap_weights(raw)

    account = get_account_dict()
    assets = max(float(account.get("total_assets", 0.0)), 1.0)
    old = {s: 0.0 for s in UNIVERSE}
    for position in account.get("positions", []):
        symbol = position.get("symbol")
        if symbol in old and float(position.get("quantity", 0.0)) > 0:
            old[symbol] = max(float(position.get("market_value", 0.0)), 0.0) / assets
    if sum(old.values()) > .001:
        target = {s: .35 * target[s] + .65 * old[s] for s in UNIVERSE}
        total = sum(target.values())
        target = {s: target[s] / total for s in UNIVERSE}

    forecast = {s: float(.012 * score[s] * (.85 if stress else 1.0)) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=FACTOR_IDS, horizon_days=10)
    WAIT = 9

