WAIT = 0


def _rank(x):
    a = sorted(x, key=lambda s: (x[s], s))
    return {s: (i + 1.0) / len(a) for i, s in enumerate(a)}


def _capped(raw, cap=0.15):
    # Iterative cap preserves non-negative full investment.
    out, active, left = {s: 0.0 for s in UNIVERSE}, set(UNIVERSE), 1.0
    while active:
        den = sum(max(raw[s], 1e-8) for s in active)
        hit = [s for s in active if left * max(raw[s], 1e-8) / den > cap]
        if not hit:
            for s in active:
                out[s] = left * max(raw[s], 1e-8) / den
            break
        for s in hit:
            out[s] = cap
            left -= cap
            active.remove(s)
    z = sum(out.values())
    return {s: out[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global WAIT
    if WAIT:
        WAIT -= 1
        return
    px = {}
