        return px[s][-1] / px[s][-n-1] - 1.0
    rets = {s: px[s][1:] / px[s][:-1] - 1.0 for s in px}
    v20 = {s: max(float(np.std(rets[s][-20:])), 0.008) for s in px}
    v40 = {s: max(float(np.std(rets[s][-40:])), 0.008) for s in px}
