    ranks = [_rank({s: f[s][j] for s in px}) for j in range(7)]
    score = {s: sum(FACTOR_WEIGHTS[j] * (ranks[j][s] - .5) for j in range(7)) for s in px}
    score.update({s: 0.0 for s in UNIVERSE if s not in score})
