from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_account_dict, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_IDS = [
    "miner_3_20310904_recovery_pullback_20d",
    "miner_3_20330610_medium_relative_contrarian_60_15d",
    "miner_1_20320624_path_stability_lead_10d",
    "miner_1_20281116_defensive_relative_lead_20d",
    "miner_1_20330204_risk_adjusted_residual_contrarian_40d",
    "miner_3_20280907_downside_asymmetry_quality_30d",
    "miner_1_20281005_vix_shock_resilient_momentum_20d",
    "miner_1_20281130_residual_volscaled_trend_20d",
]
FACTOR_WEIGHTS = [0.18, 0.16, 0.14, 0.14, 0.12, 0.10, 0.08, 0.08]
WAIT = 0


def rank01(v):
    a = sorted(v, key=lambda s: (v[s], s))
    n = max(1, len(a))
    return {s: (i + 1.0) / n for i, s in enumerate(a)}


def capped_weights(raw, cap=0.15):
    out = {s: 0.0 for s in UNIVERSE}
    active, left = set(UNIVERSE), 1.0
    while active:
        den = sum(max(raw[s], 1e-8) for s in active)
        fixed = [s for s in active if left * max(raw[s], 1e-8) / den > cap]
        if not fixed:
            for s in active:
                out[s] = left * max(raw[s], 1e-8) / den
            break
        for s in fixed:
            out[s] = cap
            left -= cap
            active.remove(s)
    z = sum(out.values())
    return {s: out[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global WAIT
    if WAIT:
        WAIT -= 1
        return
    prices = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None:
            continue
        p = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(p) > 1:
            p = p[:-1]
        if len(p) >= 125 and np.all(np.isfinite(p)) and np.all(p > 0):
            prices[s] = p
    if len(prices) < 12:
        WAIT = 9
        return

    ret = {s: prices[s][1:] / prices[s][:-1] - 1.0 for s in prices}
    mom = lambda s, n: prices[s][-1] / prices[s][-n-1] - 1.0
    m10 = {s: mom(s, 10) for s in prices}
    m20 = {s: mom(s, 20) for s in prices}
    m40 = {s: mom(s, 40) for s in prices}
    m60 = {s: mom(s, 60) for s in prices}
    avg20, avg40, avg60 = (float(np.mean(list(x.values()))) for x in (m20, m40, m60))
    vol20 = {s: max(float(np.std(ret[s][-20:])), 0.008) for s in prices}
    vol40 = {s: max(float(np.std(ret[s][-40:])), 0.008) for s in prices}
    defensive = {s for s in ("XAU", "US10Y", "CN10Y") if s in prices}
    dlead = float(np.mean([m20[s] for s in defensive])) if defensive else avg20
    breadth = sum(m40[s] > 0 for s in prices) / len(prices)
    stress = breadth < 0.45 or avg20 < -0.02

    components = {}
    for s in prices:
        r10 = ret[s][-10:]
        stability = float(np.mean(r10) / (np.std(r10) + 0.008))
        downside = float(np.std(np.minimum(r10, 0.0)))
        components[s] = [
            -(m20[s] - avg20) / vol20[s] + 0.25 * (m10[s] - m20[s]) / vol20[s],
            -(m60[s] - avg60) / vol40[s] - 0.35 * (m20[s] - avg20) / vol20[s],
            stability - 0.25 * max(0.0, -m20[s]) / vol20[s],
            -(m20[s] - dlead) / vol20[s] + (0.8 if s in defensive else 0.0),
            -(m40[s] - avg40) / vol40[s] + 0.25 * stability,
            -downside / vol20[s] - 0.35 * max(0.0, -m20[s]) / vol20[s],
            0.55 * (m10[s] - avg20) / vol20[s] + (0.5 if stress and s in defensive else 0.0),
            0.55 * (m20[s] - avg20) / vol20[s] + 0.45 * (m10[s] - m20[s]) / vol20[s],
        ]
    ranks = [rank01({s: components[s][j] for s in prices}) for j in range(8)]
    score = {s: sum(FACTOR_WEIGHTS[j] * (ranks[j][s] - 0.5) for j in range(8)) for s in prices}

    tilt = {s: 1.0 for s in UNIVERSE}
    if stress:
        tilt.update({"XAU": 1.30, "US10Y": 1.20, "CN10Y": 1.15, "BTC": 0.70,
                     "ETH": 0.68, "WTI": 0.84, "COPPER": 0.88})
    raw = {s: tilt[s] * max(0.51 + score.get(s, 0.0), 0.03) / (vol20.get(s, 0.02) ** 0.20) for s in UNIVERSE}
    target = capped_weights(raw)

    account = get_account_dict()
    assets = max(float(account.get("total_assets", 0.0)), 1.0)
    old = {s: 0.0 for s in UNIVERSE}
    for pos in account.get("positions", []):
        s = pos.get("symbol")
        if s in old and float(pos.get("quantity", 0.0)) > 0:
            old[s] = max(float(pos.get("market_value", 0.0)), 0.0) / assets
    if sum(old.values()) > 0.001:
        target = {s: 0.35 * target[s] + 0.65 * old[s] for s in UNIVERSE}
        z = sum(target.values())
        target = {s: target[s] / z for s in UNIVERSE}
    forecast = {s: float(0.012 * score.get(s, 0.0) * (0.85 if stress else 1.0)) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=FACTOR_IDS, horizon_days=10)
    WAIT = 9

