def rank01(x):
    a = sorted(x, key=lambda s: (x[s], s))
    return {s: (i + 1.0) / max(1, len(a)) for i, s in enumerate(a)}

def capped(raw, cap=.15):
    # Water-filling cap, retaining a complete, normalized long-only vector.
    out, active, left = {s: 0.0 for s in UNIVERSE}, set(UNIVERSE), 1.0
    while active:
        den = sum(max(raw[s], 1e-9) for s in active)
        fixed = [s for s in active if left * max(raw[s], 1e-9) / den > cap]
        if not fixed:
            for s in active: out[s] = left * max(raw[s], 1e-9) / den
            break
        for s in fixed:
            out[s] = cap; left -= cap; active.remove(s)
    z = sum(out.values())
    return {s: out[s] / z for s in UNIVERSE}

