import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_account_dict, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_IDS = [
    "risk_adjusted_residual_contrarian_40d",
    "miner_3_20330610_medium_relative_contrarian_60_15d",
    "miner_1_20320624_path_stability_lead_10d",
    "miner_1_20330401_compression_reversal_10d",
    "miner_2_20321125_quiet_reversal_40d_q60",
    "miner_2_20320708_short_dispersion_pullback_5d_10d",
    "miner_1_20311113_residual_momentum_20d",
    "miner_1_20281116_defensive_relative_lead_20d",
]
FACTOR_WEIGHTS = np.array([.16, .18, .14, .10, .12, .10, .10, .10])
WAIT = 0


def rank01(x):
    keys = sorted(x, key=lambda s: (x[s], s))
    n = max(len(keys), 1)
    return {s: (i + 1.0) / n for i, s in enumerate(keys)}


def capped_weights(raw, cap=.15):
    # Iterative capped simplex projection; always returns all 15 assets.
    out = {s: 0.0 for s in UNIVERSE}
    active = set(UNIVERSE)
    left = 1.0
    while active:
        denom = sum(max(raw[s], 1e-8) for s in active)
        hit = [s for s in active if left * max(raw[s], 1e-8) / denom > cap]
        if not hit:
            for s in active:
                out[s] = left * max(raw[s], 1e-8) / denom
            break
        for s in hit:
            out[s] = cap
            left -= cap
            active.remove(s)
    total = sum(out.values())
    return {s: out[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global WAIT
    if WAIT:
        WAIT -= 1
        return

    prices, rets = {}, {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None:
            continue
        p = np.asarray(df.sort_values("date")["close"], dtype=float)
        # Do not use the current incomplete bar.
        if len(p) > 1:
            p = p[:-1]
        if len(p) >= 125 and np.all(np.isfinite(p)) and np.all(p > 0):
            prices[s] = p
            rets[s] = p[1:] / p[:-1] - 1.0
    if len(prices) < 12:
        WAIT = 9
        return

    def mom(s, n):
        return prices[s][-1] / prices[s][-n-1] - 1.0

    m5 = {s: mom(s, 5) for s in prices}
    m10 = {s: mom(s, 10) for s in prices}
    m15 = {s: mom(s, 15) for s in prices}
    m20 = {s: mom(s, 20) for s in prices}
    m40 = {s: mom(s, 40) for s in prices}
    m60 = {s: mom(s, 60) for s in prices}
    market20 = float(np.mean(list(m20.values())))
    market60 = float(np.mean(list(m60.values())))
    defensive = {s for s in ("XAU", "US10Y", "CN10Y") if s in prices}
    deflead = float(np.mean([m20[s] for s in defensive])) if defensive else market20

    vals = {s: [] for s in prices}
    for s in prices:
        r20 = rets[s][-20:]
        r40 = rets[s][-40:]
        vol = max(float(np.std(r20)), .008)
        path = max(float(np.std(r40)), .008)
        # Causal proxies preserve the ensemble's directions and horizon.
        vals[s] = [
            -(m40[s] - market60) / path,                 # residual contrarian
            -(m60[s] - market60) / path,                 # medium relative contrarian
            m10[s] / vol - .35 * path / vol,             # path stability lead
            -(m5[s] - m15[s]) / vol,                     # compression reversal
            -(.55 * m40[s] + .45 * m20[s]) / path,       # quiet reversal
